"use client";

import * as React from "react";
import { Progress as ProgressPrimitive } from "@base-ui/react/progress";

import { cn } from "@/lib/utils";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/**
 * Firefly Progress: a 0.5rem warm track with a flat yellow-green fill.
 * Progress reports state, so it does not glow; only filled controls wear
 * the lit material. Leave `value` unset for an unknown amount, and a short
 * fill pulses instead.
 */
const Progress = React.forwardRef<
  HTMLDivElement,
  Omit<WithClassName<ProgressPrimitive.Root.Props>, "value"> & {
    value?: ProgressPrimitive.Root.Props["value"];
  }
>(({ className, value, ...props }, ref) => (
  <ProgressPrimitive.Root
    ref={ref}
    data-slot="progress"
    value={value ?? null}
    className={cn(
      "relative h-2 w-full overflow-hidden rounded-full bg-(--surface-3)",
      className,
    )}
    {...props}
  >
    <ProgressPrimitive.Track data-slot="progress-track" className="size-full">
      <ProgressPrimitive.Indicator
        data-slot="progress-indicator"
        className="h-full rounded-full bg-primary ring-1 ring-inset ring-(--accent-line) transition-[width] duration-base ease-out data-[indeterminate]:w-1/3 data-[indeterminate]:animate-pulse"
      />
    </ProgressPrimitive.Track>
  </ProgressPrimitive.Root>
));
Progress.displayName = "Progress";

export { Progress };
